Explain the data structures and algorithms that you would use to design an in-memory file system. Illustrate with an example in the code logic where possible.   Asked In: AmazonA file system, in its most simplistic version, consists of Files and Directories. Each Directory contains a set of Files and Directories. Since Files and Directories share so many characteristics, we've implemented them such that they inherit from the same class, Entry.   Implemented Main logic in Java
            C++

    #include <iostream>
#include <vector>
#include <string>
#include <ctime>

// Entry is superclass for both File and Directory
class Entry {
protected:
    Entry* parent;
    long created;
    long lastUpdated;
    long lastAccessed;
    std::string name;

public:
    Entry(std::string n, Entry* p) {
        name = n;
        parent = p;
        created = lastUpdated = lastAccessed = std::time(nullptr);
    }

    bool deleteEntry() {
        if (parent == nullptr)
            return false;
        return parent->deleteEntry(this);
    }

    virtual int size() = 0;

    // Getters and setters
    long getCreationTime() {
        return created;
    }

    long getLastUpdatedTime() {
        return lastUpdated;
    }

    long getLastAccessedTime() {
        return lastAccessed;
    }

    void changeName(std::string n) {
        name = n;
    }

    std::string getName() {
        return name;
    }
};

// A class to represent a File (Inherits from Entry)
class File : public Entry {
private:
    std::string content;
    int size;

public:
    File(std::string n, Entry* p, int sz) : Entry(n, p) {
        size = sz;
    }

    int size() override {
        return size;
    }

    std::string getContents() {
        return content;
    }

    void setContents(std::string c) {
        content = c;
    }
};

// A class to represent a Directory (Inherits from Entry)
class Directory : public Entry {
private:
    std::vector<Entry*> contents;

public:
    Directory(std::string n, Entry* p) : Entry(n, p) {}

    int size() override {
        int size = 0;
        for (Entry* e : contents)
            size += e->size();
        return size;
    }

    int numberOfFiles() {
        int count = 0;
        for (Entry* e : contents) {
            if (dynamic_cast<Directory*>(e)) {
                count++; // Directory counts as a file
                Directory* d = dynamic_cast<Directory*>(e);
                count += d->numberOfFiles();
            } else if (dynamic_cast<File*>(e))
                count++;
        }
        return count;
    }

    bool deleteEntry(Entry* entry) {
        return contents.erase(std::remove(contents.begin(), contents.end(), entry), contents.end()) > contents.end();
    }

    void addEntry(Entry* entry) {
        contents.push_back(entry);
    }

    std::vector<Entry*> getContents() {
        return contents;
    }
};

int main() {
    Directory root("root", nullptr);

    File file1("file1.txt", &root, 100);
    File file2("file2.txt", &root, 200);

    root.addEntry(&file1);
    root.addEntry(&file2);

    std::cout << "Total size: " << root.size() << std::endl;
    std::cout << "Total files: " << root.numberOfFiles() << std::endl;

    return 0;
}


