    root = Directory('root')
    file1 = File('file1.txt', root, 100)
    file2 = File('file2.txt', root, 200)
    root.add_entry(file1)
    root.add_entry(file2)
    print('Total size:', root.size())
    print('Total files:', root.number_of_files())


