class File extends Entry {
    constructor(n, p, sz) {
        super(n, p);
        this.size = sz;
    }

    size() {
        return this.size;
    }

    getContents() {
        return this.content;
    }

    setContents(c) {
        this.content = c;
    }
}

class Directory extends Entry {
    constructor(n, p = null) {
        super(n, p);
        this.contents = [];
    }

    size() {
        let size = 0;
        for (let e of this.contents)
            size += e.size();
        return size;
    }

    numberOfFiles() {
        let count = 0;
        for (let e of this.contents) {
            if (e instanceof Directory) {
                count++; // Directory counts as a file
                count += e.numberOfFiles();
            } else if (e instanceof File)
                count++;
        }
        return count;
    }

    deleteEntry(entry) {
        const index = this.contents.indexOf(entry);
        if (index!== -1) {
            this.contents.splice(index, 1);
            return true;
        }
        return false;
    }

    addEntry(entry) {
        this.contents.push(entry);
    }

    getContents() {
        return this.contents;
    }
}

